import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Automation — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Automation — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/automation"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Automation — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/automation"}]]},"headers":[],"relativePath":"deployment/automation.md","filePath":"deployment/automation.md","lastUpdated":1788477803000}'),n={name:"deployment/automation.md"};function d(c,e,r,l,s,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="automation-—-production-guide" tabindex="-1">Automation — Production Guide <a class="header-anchor" href="#automation-—-production-guide" aria-label="Permalink to &quot;Automation — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>automation</code></li><li>Billable marketplace add-on (<code>is_default_included: false</code>, <code>is_billable: true</code>)</li><li>Catalog version: <strong>1.0.0</strong></li><li>Initial price: <strong>$29 / month</strong>, <strong>$290 / year</strong> (same tier as Branded)</li><li>Workspaces must install from Marketplace; migrate does <strong>not</strong> auto-install</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>Data migrations (production-safe):</p><ol><li><code>register_automation_module</code> — <code>DefaultModuleRegistrar::ensureModule</code></li><li><code>add_automation_permissions</code> — <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions</code></li><li>Schema: <code>automation_workflows</code>, <code>automation_triggers</code>, <code>automation_conditions</code>, <code>automation_actions</code>, <code>automation_runs</code>, <code>automation_logs</code></li></ol><p>Keep <code>CatalogSeeder</code> in sync for local/CI fresh DBs only.</p><h2 id="queue-scheduler" tabindex="-1">Queue &amp; scheduler <a class="header-anchor" href="#queue-scheduler" aria-label="Permalink to &quot;Queue &amp; scheduler&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Worker / command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>php artisan queue:work redis --queue=automations,emails,default --sleep=1 --tries=3 --timeout=90 --max-time=3600</code></td><td>Execute workflow actions (include <code>automations</code> before <code>default</code>)</td></tr><tr><td><code>automation:dispatch-schedules</code></td><td>Every minute, <code>withoutOverlapping(5)</code>, <code>onOneServer</code> — due schedule triggers</td></tr></tbody></table><p>Shared cache driver required for <code>onOneServer()</code> locks. Schedule matching uses a <strong>90-second</strong> window after the configured <code>H:i</code> (workspace timezone) and skips a workflow that already has a <code>schedule</code> run in the last <strong>2 minutes</strong>.</p><h2 id="outbound-webhooks" tabindex="-1">Outbound webhooks <a class="header-anchor" href="#outbound-webhooks" aria-label="Permalink to &quot;Outbound webhooks&quot;">​</a></h2><ul><li>Action type <code>webhook</code> posts JSON with optional HMAC (<code>X-EloSync-Signature</code>) from the action secret or <code>AUTOMATION_WEBHOOK_SECRET</code> / <code>services.automation.webhook_secret</code>.</li><li>SSRF guard: <code>http</code>/<code>https</code> only; loopback, <code>.local</code> / <code>.localhost</code>, and private/reserved IPs are rejected. Connect timeout 5s, request timeout 15s, retry twice.</li><li>Job <code>ExecuteAutomationRunJob::failed()</code> marks the run <code>failed</code> after retries so Runs UI does not stay on <code>running</code>.</li></ul><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Run status: <code>pending</code> / <code>running</code> / <code>completed</code> / <code>failed</code> / <code>skipped</code> / <code>cancelled</code></li><li>Step detail in <code>automation_logs</code></li><li>Platform audit on workflow CRUD (via <code>PlatformAuditService</code>)</li><li>Spatie activity log on <code>AutomationWorkflow</code></li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li><code>php artisan migrate --force</code> (Automation schema + catalog + permission grants). Do <strong>not</strong> <code>db:seed</code>.</li><li>Deploy Backend + Frontend</li><li>Start / update queue workers to include <code>automations</code> (Forge daemon or Cloud background process)</li><li>Confirm scheduler runs <code>automation:dispatch-schedules</code></li><li>Optional: set <code>AUTOMATION_WEBHOOK_SECRET</code> for default webhook HMAC when actions omit a secret</li><li>Smoke: Marketplace install → create from template → activate → manual run → Runs page shows completed/failed with logs</li></ol><p>Full go-live checklist: <a href="./automation-production-readiness">Automation production readiness</a>.</p>',17)])])}const p=o(n,[["render",d]]);export{h as __pageData,p as default};
